def transform(grid):
    """Reduce each 3x3 tile to its non-background color (0 and 5 are background)."""
    out = []
    for r in range(0, len(grid), 3):
        row = []
        for c in range(0, len(grid[0]), 3):
            colors = {grid[i][j] for i in range(r, min(r + 3, len(grid)))
                      for j in range(c, min(c + 3, len(grid[0])))} - {0, 5}
            row.append(next(iter(colors)) if colors else 0)
        out.append(row)
    return out
